import numpy as np
from scipy.integrate import solve_ivp
from solver import Solver

def reference_solve(problem):
    t0, t1 = problem['t0'], problem['t1']
    y0 = np.array(problem['y0'])
    beta = problem['params']['beta']
    sigma = problem['params']['sigma']
    gamma = problem['params']['gamma']
    omega = problem['params']['omega']

    def rhs(t, y):
        S, E, I, R = y
        return [-beta*S*I + omega*R, beta*S*I - sigma*E, sigma*E - gamma*I, gamma*I - omega*R]

    sol = solve_ivp(rhs, [t0, t1], y0, method='DOP853', rtol=1e-11, atol=1e-13)
    y_final = sol.y[:, -1]
    y_final = y_final / np.sum(y_final)
    return y_final.tolist()

# Test cases
test_cases = [
    {
        't0': 0.0, 't1': 400.0,
        'y0': [0.89, 0.01, 0.005, 0.095],
        'params': {'beta': 0.35, 'sigma': 0.2, 'gamma': 0.1, 'omega': 0.002}
    },
    {
        't0': 0.0, 't1': 100.0,
        'y0': [0.7, 0.2, 0.05, 0.05],
        'params': {'beta': 0.5, 'sigma': 0.3, 'gamma': 0.15, 'omega': 0.005}
    },
    {
        't0': 0.0, 't1': 50.0,
        'y0': [0.95, 0.02, 0.02, 0.01],
        'params': {'beta': 1.0, 'sigma': 0.5, 'gamma': 0.3, 'omega': 0.01}
    },
    {
        't0': 0.0, 't1': 10.0,
        'y0': [0.6, 0.3, 0.05, 0.05],
        'params': {'beta': 0.2, 'sigma': 0.1, 'gamma': 0.05, 'omega': 0.001}
    },
    {
        't0': 0.0, 't1': 200.0,
        'y0': [0.8, 0.1, 0.05, 0.05],
        'params': {'beta': 0.8, 'sigma': 0.4, 'gamma': 0.2, 'omega': 0.003}
    },
]

s = Solver()
for i, prob in enumerate(test_cases):
    result = s.solve(prob)
    ref = reference_solve(prob)
    max_err = max(abs(np.array(result) - np.array(ref)))
    print(f'Test {i}: max_err={max_err:.2e}, sum={sum(result):.10f}, result={result}')

print()
print('All tests passed!')
"

