import numpy as np
from scipy.integrate import solve_ivp
from solver import Solver
import time

def reference_solve(problem):
    t0, t1 = problem['t0'], problem['t1']
    y0 = np.array(problem['y0'])
    beta = problem['params']['beta']
    sigma = problem['params']['sigma']
    gamma = problem['params']['gamma']
    omega = problem['params']['omega']

    def rhs(t, y):
        S, E, I, R = y
        return [-beta*S*I + omega*R, beta*S*I - sigma*E, sigma*E - gamma*I, gamma*I - omega*R]

    sol = solve_ivp(rhs, [t0, t1], y0, method='DOP853', rtol=1e-11, atol=1e-13)
    y_final = sol.y[:, -1]
    y_final = y_final / np.sum(y_final)
    return y_final.tolist()

s = Solver()

# Edge cases
edge_cases = [
    # Very long time horizon
    {
        't0': 0.0, 't1': 1000.0, 'y0': [0.9, 0.05, 0.03, 0.02],
        'params': {'beta': 0.3, 'sigma': 0.2, 'gamma': 0.1, 'omega': 0.001}
    },
    # Fast dynamics
    {
        't0': 0.0, 't1': 5.0, 'y0': [0.7, 0.2, 0.05, 0.05],
        'params': {'beta': 10.0, 'sigma': 5.0, 'gamma': 3.0, 'omega': 0.5}
    },
    # Very slow immunity loss
    {
        't0': 0.0, 't1': 100.0, 'y0': [0.8, 0.1, 0.05, 0.05],
        'params': {'beta': 0.5, 'sigma': 0.3, 'gamma': 0.2, 'omega': 1e-6}
    },
    # High transmission
    {
        't0': 0.0, 't1': 30.0, 'y0': [0.95, 0.03, 0.01, 0.01],
        'params': {'beta': 2.0, 'sigma': 1.0, 'gamma': 0.5, 'omega': 0.02}
    },
]

for i, prob in enumerate(edge_cases):
    result = s.solve(prob)
    ref = reference_solve(prob)
    max_err = max(abs(np.array(result) - np.array(ref)))
    print(f'Edge {i}: max_err={max_err:.2e}, sum={sum(result):.10f}')

# Timing
import time
prob = edge_cases[0]
t0 = time.perf_counter()
for _ in range(100):
    s.solve(prob)
t1 = time.perf_counter()
print(f'Avg time: {(t1-t0)/100*1000:.3f} ms')
"

